// Oracle parity + analytic invariants for the S-line seismic attributes
// (sweetness / relative_impedance / dip_il / dip_xl / dip_azimuth /
// curvature_mean).
//
// Frozen case table mirrors tests/cpp/seismic_attributes/fixtures/sl_*/
// manifest.json (the audit artifact) generated by
// oracle/generate_sline_attribute_fixtures.py against the pinned
// geo-viz-engine@08851951 oracle. Comparison rules: dual criterion
// |a-e| <= max(max_abs, max_rel*|e|) over finite elements; NaN/Inf masks
// must match elementwise. Tolerances are frozen in
// docs/development/cpp-seismic-native-stack/v3-contracts.md §2/§4.

#include "fixture_io.hpp"
#include "pwb_test.hpp"

#include <array>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <map>
#include <memory>
#include <string>
#include <vector>

#include <pwb/science/algorithm.hpp>
#include <pwb/science/registry.hpp>
#include <pwb/science/types.hpp>
#include <pwb/seismic_attributes/attributes.hpp>

namespace {

using pwb::science::AlgorithmRegistry;
using pwb::science::AlgorithmRequestV1;
using pwb::science::IAlgorithm;
using pwb::science::Result;
using pwb::science::VolumeView;

constexpr double kTwoPi = 6.283185307179586476925286766559;

struct KernelSpec {
    const char* kernel;       // expected file suffix + registry id suffix
    const char* algorithm_id;
    std::map<std::string, std::string> params;
    double max_abs;
    double max_rel;
};

// Frozen tolerances (top-level fixtures manifest.json; >= 10x the measured
// oracle-vs-C++ deltas).
const std::vector<KernelSpec>& kernels() {
    static const std::vector<KernelSpec> table = {
        {"sweetness", "seismic.sweetness",
         {{"sample_interval", "1.0"}}, 1e-5, 1e-2},
        {"relative_impedance", "seismic.relative_impedance", {}, 1e-6, 1e-5},
        {"dip_il", "seismic.dip_il",
         {{"dt", "1.0"}, {"dx_il", "1.0"}, {"dx_xl", "1.0"}}, 1e-5, 1e-3},
        {"dip_xl", "seismic.dip_xl",
         {{"dt", "1.0"}, {"dx_il", "1.0"}, {"dx_xl", "1.0"}}, 1e-5, 1e-3},
        {"dip_azimuth", "seismic.dip_azimuth",
         {{"dt", "1.0"}, {"dx_il", "1.0"}, {"dx_xl", "1.0"}}, 1e-5, 1e-3},
        {"curvature_mean", "seismic.curvature_mean",
         {{"win_il", "3"}, {"win_xl", "3"}, {"win_t", "3"}}, 1e-4, 1e-2},
    };
    return table;
}

const std::vector<const char*>& case_names() {
    static const std::vector<const char*> names = {
        "sl_synth_32", "sl_nan_inf", "sl_constant", "sl_zeros",
        "sl_short_axes", "sl_impulse", "sl_plane", "sl_tiny_sgy_real",
    };
    return names;
}

std::map<std::string, std::array<std::int64_t, 3>> case_shapes() {
    return {
        {"sl_synth_32", {8, 6, 32}},   {"sl_nan_inf", {8, 6, 32}},
        {"sl_constant", {4, 4, 16}},   {"sl_zeros", {4, 4, 16}},
        {"sl_short_axes", {2, 3, 4}},  {"sl_impulse", {6, 5, 24}},
        {"sl_plane", {6, 5, 20}},      {"sl_tiny_sgy_real", {8, 8, 32}},
    };
}

std::vector<float> run_attribute(const AlgorithmRegistry& registry,
                                 const std::string& algorithm_id,
                                 const std::vector<float>& input,
                                 const std::array<std::int64_t, 3>& shape,
                                 const std::map<std::string, std::string>& params) {
    IAlgorithm* algorithm = registry.find(algorithm_id);
    PWB_CHECK_MSG(algorithm != nullptr,
                  ("algorithm not registered: " + algorithm_id).c_str());
    AlgorithmRequestV1 request;
    request.algorithm_id = algorithm_id;
    request.algorithm_version = algorithm->descriptor().version;
    request.params_json = params;
    auto holder = std::make_shared<std::vector<float>>(input);
    VolumeView view;
    view.data = holder->data();
    view.shape = shape;
    view.strides = {0, 0, 0};  // packed C-order
    view.lifetime = holder;
    request.input_volumes.push_back(view);
    Result<pwb::science::AlgorithmResultV1> result =
        algorithm->run(request, nullptr, {});
    if (!result.has_value()) {
        PWB_FAIL("algorithm run failed unexpectedly on oracle case");
        return {};
    }
    PWB_CHECK(result.value().outputs.size() == 1);
    const VolumeView& produced = result.value().outputs[0].volume;
    return {produced.data,
            produced.data + static_cast<std::size_t>(produced.size())};
}

const AlgorithmRegistry& shared_registry() {
    static AlgorithmRegistry registry;
    static const bool registered = [] {
        const auto report =
            pwb::seismic_attributes::register_seismic_attributes(registry,
                                                                 "test-build");
        return report.registered_ids.size() == 10 && report.rejection.empty();
    }();
    PWB_CHECK(registered);
    return registry;
}

struct CompareSummary {
    std::size_t n = 0;
    std::size_t mask_mismatch = 0;
    double max_abs = 0.0;
    double max_rel = 0.0;
};

bool compare_expected(const std::vector<float>& actual,
                      const std::vector<float>& expected, double max_abs_tol,
                      double max_rel_tol, CompareSummary& summary) {
    if (actual.size() != expected.size()) {
        std::fprintf(stderr, "size mismatch: actual=%zu expected=%zu\n",
                     actual.size(), expected.size());
        return false;
    }
    summary = CompareSummary{};
    summary.n = expected.size();
    bool ok = true;
    for (std::size_t i = 0; i < expected.size(); ++i) {
        const double e = static_cast<double>(expected[i]);
        const double a = static_cast<double>(actual[i]);
        const bool e_bad = std::isnan(e) || std::isinf(e);
        const bool a_bad = std::isnan(a) || std::isinf(a);
        if (e_bad || a_bad) {
            // Non-finite positions (and Inf signs) must match exactly.
            const bool e_nan = std::isnan(e);
            const bool a_nan = std::isnan(a);
            const bool match = e_nan == a_nan && std::isinf(e) == std::isinf(a)
                               && (!std::isinf(e) || (e > 0) == (a > 0));
            if (!match) {
                ++summary.mask_mismatch;
                ok = false;
            }
            continue;
        }
        const double diff = std::fabs(a - e);
        if (diff > summary.max_abs) {
            summary.max_abs = diff;
        }
        if (std::fabs(e) > 1e-6) {
            const double rel = diff / std::fabs(e);
            if (rel > summary.max_rel) {
                summary.max_rel = rel;
            }
        }
        const double allowed =
            std::max(max_abs_tol, max_rel_tol * std::fabs(e));
        if (!(diff <= allowed)) {
            ok = false;
        }
    }
    return ok;
}

}  // namespace

TEST(fixtures_parity) {
    const AlgorithmRegistry& registry = shared_registry();
    const std::filesystem::path root = fixture_io::fixture_root();
    const auto shapes = case_shapes();
    std::size_t failures = 0;
    for (const char* case_name : case_names()) {
        const std::vector<float> input =
            fixture_io::read_f32(root / case_name / "input.f32");
        PWB_CHECK_MSG(!input.empty(),
                      (std::string("missing input fixture: ") + case_name)
                          .c_str());
        const auto shape = shapes.at(case_name);
        for (const KernelSpec& kernel : kernels()) {
            const std::vector<float> expected = fixture_io::read_f32(
                root / case_name
                / (std::string("expected_") + kernel.kernel + ".f32"));
            PWB_CHECK_MSG(!expected.empty(),
                          (std::string("missing expected for ") + case_name
                           + "/" + kernel.kernel)
                              .c_str());
            const std::vector<float> actual = run_attribute(
                registry, kernel.algorithm_id, input, shape, kernel.params);
            CompareSummary summary;
            const bool ok = compare_expected(actual, expected, kernel.max_abs,
                                             kernel.max_rel, summary);
            char buffer[512];
            std::snprintf(buffer, sizeof(buffer),
                          "%s/%s n=%zu mask_mismatch=%zu max_abs=%.3e "
                          "max_rel=%.3e -> %s",
                          case_name, kernel.kernel, summary.n,
                          summary.mask_mismatch, summary.max_abs,
                          summary.max_rel, ok ? "PASS" : "FAIL");
            if (!ok) {
                ++failures;
            }
            std::printf("%s\n", buffer);
        }
    }
    PWB_CHECK_MSG(failures == 0, "some S-line parity checks failed");
}

TEST(sl_plane_analytic) {
    // The slanted plane vol[il,xl,t] = 0.7*il - 0.4*xl + 1.3*t + 2 has
    // analytic dips atan2(0.7, 1.3) and atan2(-0.4, 1.3) everywhere.
    const AlgorithmRegistry& registry = shared_registry();
    const std::filesystem::path root = fixture_io::fixture_root();
    const std::vector<float> input =
        fixture_io::read_f32(root / "sl_plane" / "input.f32");
    PWB_CHECK(input.size() == 6u * 5u * 20u);
    const std::map<std::string, std::string> dip_params = {
        {"dt", "1.0"}, {"dx_il", "1.0"}, {"dx_xl", "1.0"}};
    const std::vector<float> dip_il =
        run_attribute(registry, "seismic.dip_il", input, {6, 5, 20},
                      dip_params);
    const std::vector<float> dip_xl =
        run_attribute(registry, "seismic.dip_xl", input, {6, 5, 20},
                      dip_params);
    const double want_il = std::atan2(0.7, 1.3);
    const double want_xl = std::atan2(-0.4, 1.3);
    // The plane itself is float32-quantized (values up to ~31, ulp ~2e-6),
    // so the analytic dip holds only to the f32 rounding of the input.
    for (std::size_t i = 0; i < dip_il.size(); ++i) {
        PWB_CHECK_MSG(std::fabs(static_cast<double>(dip_il[i]) - want_il)
                          < 1e-4,
                      "plane dip_il analytic mismatch");
        PWB_CHECK_MSG(std::fabs(static_cast<double>(dip_xl[i]) - want_xl)
                          < 1e-4,
                      "plane dip_xl analytic mismatch");
    }
    const std::vector<float> azimuth = run_attribute(
        registry, "seismic.dip_azimuth", input, {6, 5, 20}, dip_params);
    for (std::size_t i = 0; i < azimuth.size(); ++i) {
        PWB_CHECK_MSG(azimuth[i] >= 0.0f && azimuth[i] < static_cast<float>(
                                                  kTwoPi),
                      "azimuth outside [0, 2*pi)");
    }
}

TEST(azimuth_consistency) {
    // dip_azimuth == atan2(sin? no: wrap(atan2(dip_xl, dip_il))) recomputed
    // from the two dip volumes — a cross-kernel identity on the real case.
    const AlgorithmRegistry& registry = shared_registry();
    const std::filesystem::path root = fixture_io::fixture_root();
    const std::vector<float> input =
        fixture_io::read_f32(root / "sl_tiny_sgy_real" / "input.f32");
    const std::map<std::string, std::string> dip_params = {
        {"dt", "1.0"}, {"dx_il", "1.0"}, {"dx_xl", "1.0"}};
    const std::vector<float> dip_il =
        run_attribute(registry, "seismic.dip_il", input, {8, 8, 32},
                      dip_params);
    const std::vector<float> dip_xl =
        run_attribute(registry, "seismic.dip_xl", input, {8, 8, 32},
                      dip_params);
    const std::vector<float> azimuth = run_attribute(
        registry, "seismic.dip_azimuth", input, {8, 8, 32}, dip_params);
    for (std::size_t i = 0; i < azimuth.size(); ++i) {
        const double expected =
            std::atan2(static_cast<double>(dip_xl[i]),
                       static_cast<double>(dip_il[i]));
        double wrapped = expected < 0.0 ? expected + kTwoPi : expected;
        if (std::isnan(wrapped)) {
            PWB_CHECK(std::isnan(static_cast<double>(azimuth[i])));
            continue;
        }
        PWB_CHECK_MSG(
            std::fabs(wrapped - static_cast<double>(azimuth[i])) < 1e-6,
            "azimuth identity mismatch");
    }
}

TEST(rejects_degenerate_axes) {
    // np.gradient raises on axes with fewer than 2 samples; the kernels
    // refuse honestly instead of producing garbage.
    const AlgorithmRegistry& registry = shared_registry();
    const std::vector<float> flat(24, 0.0f);
    const std::map<std::string, std::string> dip_params = {
        {"dt", "1.0"}, {"dx_il", "1.0"}, {"dx_xl", "1.0"}};
    for (const std::array<std::int64_t, 3>& shape :
         {std::array<std::int64_t, 3>{1, 4, 6}, {3, 1, 6}, {3, 4, 1}}) {
        for (const char* id : {"seismic.dip_il", "seismic.dip_xl",
                               "seismic.dip_azimuth",
                               "seismic.curvature_mean"}) {
            IAlgorithm* algorithm = registry.find(id);
            AlgorithmRequestV1 request;
            request.algorithm_id = id;
            request.algorithm_version = algorithm->descriptor().version;
            request.params_json = dip_params;
            auto holder = std::make_shared<std::vector<float>>(flat);
            VolumeView view;
            view.data = holder->data();
            view.shape = shape;
            view.strides = {0, 0, 0};
            view.lifetime = holder;
            request.input_volumes.push_back(view);
            auto result = algorithm->run(request, nullptr, {});
            PWB_CHECK_MSG(result.is_error(),
                          (std::string(id) + " accepted a degenerate axis")
                              .c_str());
        }
    }
}

int main() {
    for (const auto& test : pwb_test::registry()) {
        std::printf("== %s ==\n", test.name.c_str());
        test.body();
    }
    std::printf("all S-line attribute tests passed (%zu tests)\n",
                pwb_test::registry().size());
    return 0;
}
